        #region Unity framework Inspector logic
        void OnValidate()
        {
            //By default, we automatically search for those Producers but we can plug any other compatible Producers     
            if (posColMapSources != null)
            {
                for (int i = 0; i < posColMapSources.Length; ++i)
                {
                    if (posColMapSources[i] is not ISourceModule<GPUPointCloud>)
                    {
                        posColMapSources[i] = (Component)posColMapSources[i]?.GetComponents<ISourceModule<GPUPointCloud>>().Last();
                    }
                }
            }
        }

        protected void Start()
        {
            //RGBok = new bool[colorSources.Length]; 
            //DepthOk = new bool[colorSources.Length]; 
            colorIsHotInitComplete = new bool[posColMapSources.Length];

            colorSourcesFinished = new bool[posColMapSources.Length];

            posColMapFrameID = new int[posColMapSources.Length];
            PrepareAdaptativeProjection();


            //Do the Events connections in Start as the GameObjects need to exist
            Connect();
        }

        protected override void OnDestroy()
        {
            base.OnDestroy();
            Disconnect();
        }
        #endregion

        protected void Connect()
        {
            foreach (var colorSource in posColMapSources)
            {
                ((ISourceModule<GPUPointCloud>)colorSource).OutputReady += ColorsRGBReady;
                ((ISourceModule<GPUPointCloud>)colorSource).HotInitialized += OnHotInitFromSource;
                ((ISourceModule<GPUPointCloud>)colorSource).HasFinished += OnHasFinishedFromSource;

            }
        }

        protected void Disconnect()
        {
            foreach (var colorSource in posColMapSources)
            {
                ((ISourceModule<GPUPointCloud>)colorSource).OutputReady -= ColorsRGBReady;
                ((ISourceModule<GPUPointCloud>)colorSource).HotInitialized -= OnHotInitFromSource;
                ((ISourceModule<GPUPointCloud>)colorSource).HasFinished -= OnHasFinishedFromSource;

            }
        }

        void OnHotInitFromSource(object sender, EventArgs e)
        {
            //Debug.Log("OnHotInitFromSource in MULTICOMBINATOR " + this.GetType().Name + " (" + this.name + ")");
            IsHotInitComplete = false;
            for (int i = 0; i < colorIsHotInitComplete.Length; ++i)
            {
                colorIsHotInitComplete[i] = false;

                colorSourcesFinished[i] = false;

            }
        }

        void OnHasFinishedFromSource(object sender, EventArgs e)
        {
            int indexColor = Array.IndexOf(posColMapSources, sender);

            if (indexColor != -1) { colorSourcesFinished[indexColor] = true; }

            if (AllTrue(colorSourcesFinished))
            {
                FinishProcess();
                HasFinished?.Invoke(this, EventArgs.Empty);
                for (int i = 0; i < posColMapSources.Length; ++i)
                {
                    colorSourcesFinished[i] = false;
                }
            }
        }

        bool AllTrue(bool[] _boolArray)
        {
            bool retvalue = true;
            foreach (bool value in _boolArray)
            { retvalue &= value; }
            return retvalue;
        }

        public override void FinishProcess()
        {
            Debug.Log("SPECIAL --- FinishProcess in " + this.GetType().Name);
        }

        protected void InitByColor(int streamIndex, GPUPointCloud gPUPointCloud, FrameInfo frameInfo)
        {
            if (alignmentMatrices == null)
            {
                alignmentMatrices = new Matrix4x4[posColMapSources.Length];
            }
            alignmentMatrices[streamIndex] = gPUPointCloud.appliedMatrix;
            //Debug.Log($"matrix for {streamIndex} is {gPUPointCloud.appliedMatrix}");
            containerRes.width = gPUPointCloud.positionMap.width;
            containerRes.height = gPUPointCloud.positionMap.height;



            colorIsHotInitComplete[streamIndex] = true;
            try
            {
                if (ContextManager.instance == null) { ContextManager.TryFindInstance(); }
                var ctxt = ContextManager.instance?.currentContext;
                if (ctxt != null)
                {
                    if (ctxt.FusionConfig == null)
                    {
                        ctxt.FusionConfig = new();
                    }
                    ctxt.FusionConfig.exportType = ExportType.PerspectiveProjected;
                    if (ctxt.FusionConfig.virtualCamConfigs == null)
                    {
                        ctxt.FusionConfig.virtualCamConfigs = new();
                    }
                    var foundConfig = ctxt.FusionConfig.virtualCamConfigs.Where(c => c.UserAssignedCameraIndex == frameInfo.cameraIndex).FirstOrDefault();
                    if (foundConfig == null/* && Helper.GetCamIndex(gameObject) == Helper.GetCamIndex(cam.gameObject)*/)
                    {
                        ctxt.FusionConfig.virtualCamConfigs.Add(ctxt.CamConfig(frameInfo.cameraIndex).Copy());
                        foundConfig = ctxt.FusionConfig.virtualCamConfigs.Last();
                    }
                    foundConfig.alignmentMatrix = Matrix4x4.TRS(Origin, Box.transform.rotation, Vector3.one);
                    foundConfig.alignmentMatrixPath = Path.Combine(ctxt.Sequence, "alignMatrix_" + frameInfo.cameraIndex + ".json");
                    foundConfig.screenCameraDistance = Box.transform.localPosition.z;
                    foundConfig.projectonScreenWidth = Box.transform.localScale.x;
                    foundConfig.projectonScreenHeight = Box.transform.localScale.y;
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning("In case you are trying to export a perspective fusion, for the creation of the metadata file a Context manager is needed. Otherwise you can ignore this warning");
            }
            if (colorIsHotInitComplete.All(x => x)) HotInit();
        }

        public override void HotInit()
        {

            //Debug.Log("HotInit in MULTICOMBINATOR " + this.GetType().Name + " (" + this.name + ")");
            TaaCurrentDelay = TaaDelay;

            PrepareOutPositionBuffer();
            PrepareOutColorBuffer();
            PrepareDepthMap();

            PreparePositionTextureArray();
            PrepareColorTextureArray();

            PrepareComputeShader();

            AddAllCamstoFusion();

            //base.HotInit();
            IsHotInitComplete = true;
            HotInitialized?.Invoke(this, EventArgs.Empty);
        }

        protected void AddAllCamstoFusion()
        {
            //Give to posColMapToFuse list the full list of the posColMapSources array
            posColMapToFuse.Clear();
            for (int i = 0; i < posColMapSources.Length; ++i)
            {
                posColMapToFuse.Add(posColMapSources[i]);
            }
            allCamsToFuse = true;
        }

