        protected void PrepareOutPositionBuffer()
        {
            positionsOut1 = new RenderTexture(finalWidth, finalHeight, 0, RenderTextureFormat.ARGBFloat)
            {
                enableRandomWrite = true,
                useMipMap = false,
                filterMode = FilterMode.Point,
                name = "perspPosOut1"
            };
            positionsOut1.Create();
            positionsOut2 = new RenderTexture(finalWidth, finalHeight, 0, RenderTextureFormat.ARGBFloat)
            {
                enableRandomWrite = true,
                useMipMap = false,
                filterMode = FilterMode.Point,
                name = "perspPosOut2"
            };
            positionsOut2.Create();
        }

        protected void PrepareOutColorBuffer()
        {
            colorsOut1 = new RenderTexture(finalWidth, finalHeight, 0, RenderTextureFormat.ARGB32) //ARGBFloat cos BGRA32 comes with a gamma
            {
                graphicsFormat = UnityEngine.Experimental.Rendering.GraphicsFormat.R8G8B8A8_UNorm,
                enableRandomWrite = true,
                useMipMap = false,
                filterMode = FilterMode.Point,
                name = "perspColOut1"
            };
            colorsOut1.Create();
            colorsOut2 = new RenderTexture(finalWidth, finalHeight, 0, RenderTextureFormat.ARGB32) //ARGBFloat cos BGRA32 comes with a gamma
            {
                graphicsFormat = UnityEngine.Experimental.Rendering.GraphicsFormat.R8G8B8A8_UNorm,
                enableRandomWrite = true,
                useMipMap = false,
                filterMode = FilterMode.Point,
                name = "perspColOut2"
            };
            colorsOut2.Create();
        }
        protected void PrepareDepthMap()
        {
            depthMap = new RenderTexture(finalWidth, finalHeight, 0, RenderTextureFormat.RInt);
            depthMap.enableRandomWrite = true;
            depthMap.Create();
        }
        protected void PreparePositionTextureArray()
        {
            positionHistory = new RenderTexture(finalWidth, finalHeight, 0)
            {
                format = positionsOut1.format,
                graphicsFormat = positionsOut1.graphicsFormat,
                dimension = UnityEngine.Rendering.TextureDimension.Tex2DArray,
                volumeDepth = TaaDelay * 2 + 1,
                enableRandomWrite = true,
                useMipMap = false,
                name = "historyDepthArray"
            };
            positionHistory.Create();
        }
        protected void PrepareColorTextureArray()
        {
            colorHistory = new RenderTexture(finalWidth, finalHeight, 0)
            {
                format = colorsOut1.format,
                graphicsFormat = colorsOut1.graphicsFormat,
                dimension = UnityEngine.Rendering.TextureDimension.Tex2DArray,
                volumeDepth = TaaDelay * 2 + 1,
                enableRandomWrite = true,
                useMipMap = false,
                name = "historyColorArray"
            };
            colorHistory.Create();
        }


