        protected void PrepareComputeShader()
        {


            PerspFusionCompute = Instantiate(PerspFusionCompute); //If we don't instantiate, the same CS is used by several modules. Intéressant
            kernelIndex = PerspFusionCompute.FindKernel("CSMain");
            threadGroupsX = Mathf.CeilToInt(containerRes.width / 8);
            threadGroupsY = Mathf.CeilToInt(containerRes.height / 8);

            if (TemporalNoiseRemoverCompute != null)
            {
                TemporalNoiseRemoverCompute = Instantiate(TemporalNoiseRemoverCompute);
                kernelIndex2 = TemporalNoiseRemoverCompute.FindKernel("CSMain");
            }

            threadGroupsX2 = Mathf.CeilToInt(finalWidth / 8);
            threadGroupsY2 = Mathf.CeilToInt(finalHeight / 8);

            //OrthoFusionCompute.SetTexture(kernelIndex, ID.ColMapOut, colorsOut);
            //OrthoFusionCompute.SetTexture(kernelIndex, ID.PosMapOut, positionsOut);

            //Debug.Log("X distance : " + (Xcorner.x - Origin.x));

            //Debug.Log("Y distance : " + (Ycorner.y - Origin.y));
            //fusionDisplay.transform.position = Box.transform.TransformPoint(new Vector4(Box.GetComponent<MeshFilter>().mesh.vertices[7].x, Box.GetComponent<MeshFilter>().mesh.vertices[7].y, Box.GetComponent<MeshFilter>().mesh.vertices[7].z));
        }

        protected void PrepareAdaptativeProjection()
        {
            //Vector3[] vertices = new Vector3[24];

            /*for(int i = 0; i < vertices.Length; i++) 
            {
                vertices[i] = Box.GetComponent<MeshFilter>().mesh.vertices[i];
            }

            Box.GetComponent<MeshFilter>().mesh.vertices = vertices;

            Box.GetComponent<MeshFilter>().mesh.RecalculateBounds();*/

            //cf le schéma de la création d'un cube dans Unity 24 vertex : https://forum.unity.com/threads/cube-mesh-order-of-vertices-and-triangles.873901/ 

            //Front face of the cube
            Origin = Box.transform.TransformPoint(new Vector4(Box.GetComponent<MeshFilter>().mesh.vertices[7].x, Box.GetComponent<MeshFilter>().mesh.vertices[7].y, Box.GetComponent<MeshFilter>().mesh.vertices[7].z, 0));
            Xcorner = Box.transform.TransformPoint(new Vector4(Box.GetComponent<MeshFilter>().mesh.vertices[6].x, Box.GetComponent<MeshFilter>().mesh.vertices[6].y, Box.GetComponent<MeshFilter>().mesh.vertices[6].z, 0));
            Ycorner = Box.transform.TransformPoint(new Vector4(Box.GetComponent<MeshFilter>().mesh.vertices[5].x, Box.GetComponent<MeshFilter>().mesh.vertices[5].y, Box.GetComponent<MeshFilter>().mesh.vertices[5].z, 0));
            Zcorner = Box.transform.TransformPoint(new Vector4(Box.GetComponent<MeshFilter>().mesh.vertices[14].x, Box.GetComponent<MeshFilter>().mesh.vertices[14].y, Box.GetComponent<MeshFilter>().mesh.vertices[14].z, 0));
            //Bounding Box pivot
            //BoundingBoxPivot = Box.transform.position;

            /*Debug.Log("Origin : " + Origin);
            Debug.Log("Xcorner : " + Xcorner);
            Debug.Log("Ycorner : " + Ycorner);
            Debug.Log("Zcorner : " + Zcorner);
            Debug.Log("Bounding Box Pivot : "+ BoundingBoxPivot);*/

            //Get the world 4X4Matrix of the bounding box 
            //Take care of local and world values
            Vector3 boxScale = new Vector3(Box.transform.localScale.x, Box.transform.localScale.y, Box.transform.localScale.z); // not used 
            // Adjust box scale so it fits the camera FOV X and Y 
            //Box.transform.localScale = new Vector3(cam., 0.1f, Box.transform.localScale.z);
            //Damping function : Scaling the box to compensate the size decreasing of the image when getting closer to the box center : box scale = 1 - 1/(distance + 1)^n // not perfect but compensate well
            //Box.transform.localScale = new Vector3(1 - 1 / (Mathf.Pow((Vector3.Distance(cam.transform.position, Box.transform.position)+1), dampingPower)), 1 - 1 / (Mathf.Pow((Vector3.Distance(cam.transform.position, Box.transform.position)+1), dampingPower)), 1 - 1 / (Mathf.Pow((Vector3.Distance(cam.transform.position, Box.transform.position)+1), dampingPower)));

            //Distance constante entre la caméra et la face du cube mais pas fluide
            //Box.transform.localScale = new Vector3(0.1f, 0.1f,Vector3.Distance(cam.transform.position, Box.transform.position)*2-0.5f);//(Mathf.Pow(Vector3.Distance(cam.transform.position, Box.transform.position), 2)
            //Matrix4x4 scaleMatrix = Matrix4x4.Scale(boxScale);
            Vector3 boxPosition = Box.transform.TransformPoint(new Vector3(Box.transform.localPosition.x, Box.transform.localPosition.y, Box.transform.localPosition.z));
            Matrix4x4 translateMatrix = Matrix4x4.Translate(boxPosition);
            Quaternion boxRotation = Box.transform.rotation;
            Matrix4x4 rotateMatrix = Matrix4x4.Rotate(Quaternion.Inverse(boxRotation));
            //Matrix4x4 rotateMatrix = Matrix4x4.Rotate(boxRotation);
            //bBoxMatrix = translateMatrix * Box.transform.localToWorldMatrix;
            bBoxMatrix = rotateMatrix * Matrix4x4.identity;
            //bBoxMatrix = Matrix4x4.identity;

            //Apply cube orientation and Origin position to the GameObject Displaying the Fusion

            //TEST sans contrecarrer la rotation et la position avec la transformation de l afficheur !!!
            if (fusionDisplay != null)
            {
                fusionDisplay.transform.localRotation = boxRotation;
                fusionDisplay.transform.localPosition = new Vector3(Origin.x, Origin.y, Origin.z);
            }
            //fusionDisplay.transform.position = BoundingBoxPivot;

            //Rotate the bounding box according to the camera
            //Box.transform.rotation = Quaternion.LookRotation(Box.transform.position - cam.transform.position);



        }
        protected void PreparePosColMapToFuse() //V1.1
        {
            //A mettre dans une fonction séparée. Attention ! Doit se faire une fois par cycle de fusion pas par rajout de frame dans la fusion 
            //Debug.Log("Camera vector : " + (Vector3.Normalize(Box.transform.position - cam.transform.position)).ToString());
            posColMapToFuse.Clear();
            for (int i = 0; i < posColMapSources.Length; ++i)
            {
                Vector3 forward = alignmentMatrices[i] * Vector3.forward;

                if (Vector3.Dot(Vector3.Normalize(Box.transform.position - cam.transform.position), forward) > 0)
                {
                    posColMapToFuse.Add(posColMapSources[i]);
                }
            }
            //Debug.Log("posColoMapToFuse size : " + posColMapToFuse.Count);
            //posColMapSources = new Component[posColMapToFuse.Count];

            /*for (int i = 0; i < posColMapToFuse.Count; ++i)
            {
                posColMapSources[i] = posColMapToFuse[i];
            }*/
        }
        protected void ColorsRGBReady(object sender, DataEventArgs<GPUPointCloud> e)
        {

            //Debug.Log("frameId:" + e.FrameID);
            if (e.Output.positionMap != null && e.Output.colorMap != null)
            {
                //int index = posColMapToFuse.IndexOf((Component) sender);
                int index = Array.IndexOf(posColMapSources, sender);

                if (!colorIsHotInitComplete[index])
                {
                    InitByColor(index, e.Output, e.FrameInfo);
                }
                else if (IsHotInitComplete)
                {

                    //Ortho Fusion for each posColMapSource

                    //Debug.Log("posColMapSources Length : "+posColMapSources.Length);

                    //V1.1 : if posColMapSources arriving belongs to the posColMapToFuse List, we autorize the fusion, 
                    //Debug.Log($"Before testeing if contains : {index} {e.FrameID}");

                    if (posColMapToFuse.Contains(posColMapSources[index])) PerspFusionDataProcess(e.Output);


                    /*for (int i = 0; i < posColMapToFuse.Count; i++)
                    {
                        if (posColMapSources[index] == posColMapToFuse[i]) IsoFusionDataProcess(e.Output.Item1, e.Output.Item2);
                    }*/


                    //CopyColorIntoTexture(e.Output, index, posColMapSources.Length);
                    //Debug.Log("e.FrameID : " + e.FrameID);

                    //Debug.Log("index : " + Helper.GetCamIndex(((Component)sender).gameObject) + ", e.FrameID : " + e.FrameInfo.frameID);

                    posColMapFrameID[index] = e.FrameInfo.frameID;

                    if (posColMapFrameID.All(x => x == e.FrameInfo.frameID))
                    {
                        for (int i = 0; i < posColMapSources.Length; ++i)
                        {
                            posColMapFrameID[i] = -1;
                        }
                        //Debug.Log($"ColorReady for {e.FrameID}");
                        var gpuPointCloud = new GPUPointCloud();
                        if (usePairBuffer)
                        {
                            gpuPointCloud.positionMap = positionsOut2;
                            gpuPointCloud.colorMap = colorsOut2;
                        }
                        else
                        {
                            gpuPointCloud.positionMap = positionsOut1;
                            gpuPointCloud.colorMap = colorsOut1;
                        }
                        gpuPointCloud.appliedMatrix = Matrix4x4.TRS(Origin, Box.transform.rotation, Vector3.one);
                        OutputReady?.Invoke(this, new(gpuPointCloud, e.FrameInfo));
                        fusionDone = true;
                        usePairBuffer = !usePairBuffer;
                    }

                }
            }
        }

        protected virtual void PerspFusionDataProcess(GPUPointCloud PCin)
        {

            RenderTexture colorsOut, positionsOut;

            if (!usePairBuffer)
            {
                colorsOut = colorsOut1;
                positionsOut = positionsOut1;
            }
            else
            {
                colorsOut = colorsOut2;
                positionsOut = positionsOut2;
            }
            //Debug.Log("Fusion Done ? : " + fusionDone);
            if (fusionDone)//||fusion==false
            {
                //Graphics.SetRenderTarget(colorsOut);
                //Clear the out Rendertextures Buffers at each initialization of a new fusion
                RenderTexture.active = colorsOut;
                GL.Clear(true, true, Color.clear);
                RenderTexture.active = positionsOut;
                GL.Clear(true, true, Color.clear);
                RenderTexture.active = depthMap;
                GL.Clear(true, true, Color.clear);

                //Once by fusion cycle prepare the array of component to be fused. Only the kinects in the same axis than the main camera are fused.
                if (occludeOppositeCameras)
                {
                    PreparePosColMapToFuse();
                    allCamsToFuse = false;
                }
                else if (!occludeOppositeCameras && !allCamsToFuse)
                {
                    AddAllCamstoFusion();
                    allCamsToFuse = true;
                }
            }


            //Fusion parameters
            PerspFusionCompute.SetTexture(kernelIndex, ID.ColMapOut, colorsOut);
            PerspFusionCompute.SetTexture(kernelIndex, ID.PosMapOut, positionsOut);
            PerspFusionCompute.SetTexture(kernelIndex, ID.DepthMap, depthMap);
            //OrthoFusionCompute.SetBool(ID.startNewFusion, fusionDone);
            //PerspFusionCompute.SetBool(ID.voxelized, voxelize);
            PrepareAdaptativeProjection();
            PerspFusionCompute.SetVector(ID.O, Origin);
            PerspFusionCompute.SetVector(ID.X, Xcorner);
            PerspFusionCompute.SetVector(ID.Y, Ycorner);
            PerspFusionCompute.SetVector(ID.Z, Zcorner);
            //PerspFusionCompute.SetVector(ID.bBoxPivot, BoundingBoxPivot);

            // send the world position of the cam in the vector 4
            //Debug.Log("camera position : " + cam.transform.TransformPoint(new Vector4(cam.transform.localPosition.x, cam.transform.localPosition.y, cam.transform.localPosition.z, 0)));

            //PerspFusionCompute.SetVector(ID.camPos, cam.transform.TransformPoint(new Vector4(cam.transform.localPosition.x, cam.transform.localPosition.y, cam.transform.localPosition.z, 0)));
            //Debug.Log("camera position : " + new Vector4(cam.transform.position.x, cam.transform.position.y, cam.transform.position.z, 0));
            PerspFusionCompute.SetVector(ID.camPos, new Vector4(cam.transform.position.x, cam.transform.position.y, cam.transform.position.z, 0));

            PerspFusionCompute.SetInt(ID.orthoWidth, finalWidth);
            PerspFusionCompute.SetInt(ID.orthoHeight, finalHeight);
            PerspFusionCompute.SetInt(ID.orthoDepth, finalDepth);
            PerspFusionCompute.SetFloat(ID.depthThrsld, depthThreshold_Z_meter);
            PerspFusionCompute.SetInt(ID.Thickness, thickness);
            PerspFusionCompute.SetFloat(ID.scalarNormalLimit, scalarAngleLimit);
            PerspFusionCompute.SetMatrix(ID.bBoxMat, bBoxMatrix);
            PerspFusionCompute.SetBool(ID.FlipNormalsComparator, flipNormalsComparator);
            PerspFusionCompute.SetBool(ID.Fusion, fusion);
            //PerspFusionCompute.SetInt(ID.DebugPixelWidth, debugPixelWidth);
            //PerspFusionCompute.SetInt(ID.DebugPixelHeight, debugPixelHeight);

            // Add current frame to buffer and remove oldest if necessary
            //frameBuffer.Enqueue(new GPUPointCloud(PCin));
            //if (frameBuffer.Count > maxFrameHistory)
            //{
            //    var oldFrame = frameBuffer.Dequeue();
            //    oldFrame.Dispose();
            //}

            //int frameIndex = 0;
            //foreach (var frame in frameBuffer)
            //{
            // 
            //    {
            //        PerspFusionCompute.SetTexture(kernelIndex, ID.PosMapRead, frame.positionMap);

            //        PerspFusionCompute.SetTexture(kernelIndex, ID.ColMapRead, frame.colorMap);

            //        PerspFusionCompute.Dispatch(kernelIndex, threadGroupsX, threadGroupsY, threadGroupsZ);
            //    }

            //    frameIndex++;
            //}

            if (TaaActivated)
            {
                if (historyCleared) historyCleared = false;
                //TAA parameters
                TemporalNoiseRemoverCompute.SetInt(ID.TaaDelay, TaaDelay);
                TemporalNoiseRemoverCompute.SetInt(ID.TaaThickness, TaaThickness);
                TemporalNoiseRemoverCompute.SetFloat(ID.TaaDepthThreshold, TaaDepthThreshold);
                TemporalNoiseRemoverCompute.SetBool(ID.TaaVisualize, TaaVisualize);

                TemporalNoiseRemoverCompute.SetFloat(ID.motionThreshold, motionThreshold);
                TemporalNoiseRemoverCompute.SetBool(ID.motionVisualize, motionVisualize);

                if (TaaCurrentDelay != TaaDelay) HotInit();

                // Add current frame to buffer and remove oldest if necessary
                frameBuffer.Enqueue(new GPUPointCloud(PCin));

                while (frameBuffer.Count > TaaDelay * 2 + 1)
                {
                    var oldFrame = frameBuffer.Dequeue();
                    oldFrame.Dispose();
                }

                // Set previous frames in the compute shader

                int frameIndex = 0;
                foreach (var frame in frameBuffer)
                {

                    //PosMap Read
                    PerspFusionCompute.SetTexture(kernelIndex, ID.PosMapRead, frame.positionMap);
                    //ColMap Read
                    PerspFusionCompute.SetTexture(kernelIndex, ID.ColMapRead, frame.colorMap);

                    PerspFusionCompute.Dispatch(kernelIndex, threadGroupsX, threadGroupsY, threadGroupsZ);

                    Graphics.CopyTexture(positionsOut, 0, 0, positionHistory, frameIndex, 0);
                    Graphics.CopyTexture(colorsOut, 0, 0, colorHistory, frameIndex, 0);

                    RenderTexture.active = colorsOut;
                    GL.Clear(true, true, Color.clear);
                    RenderTexture.active = positionsOut;
                    GL.Clear(true, true, Color.clear);
                    RenderTexture.active = depthMap;
                    GL.Clear(true, true, Color.clear);



                    frameIndex++;

                }
                //Test de vizualisation de la frame Delay après traitement par la persp fusion
                //Graphics.CopyTexture(positionHistory, TaaDelay, 0,positionsOut, 0, 0);
                //Graphics.CopyTexture(colorHistory, TaaDelay, 0,colorsOut, 0, 0);

                TemporalNoiseRemoverCompute.SetTexture(kernelIndex2, ID.ColMapOut, colorsOut);
                TemporalNoiseRemoverCompute.SetTexture(kernelIndex2, ID.PosMapOut, positionsOut);

                TemporalNoiseRemoverCompute.SetTexture(kernelIndex2, ID.PositionHistory, positionHistory);
                TemporalNoiseRemoverCompute.SetTexture(kernelIndex2, ID.ColorHistory, colorHistory);
                TemporalNoiseRemoverCompute.Dispatch(kernelIndex2, threadGroupsX2, threadGroupsY2, threadGroupsZ2);
            }
            else
            {
                if (!historyCleared)
                {
                    frameBuffer.Clear();
                    RenderTexture.active = positionHistory;
                    GL.Clear(true, true, Color.clear);
                    RenderTexture.active = colorHistory;
                    GL.Clear(true, true, Color.clear);
                    historyCleared = true;
                }

                PerspFusionCompute.SetTexture(kernelIndex, ID.PosMapRead, PCin.positionMap);

                PerspFusionCompute.SetTexture(kernelIndex, ID.ColMapRead, PCin.colorMap);
                PerspFusionCompute.Dispatch(kernelIndex, threadGroupsX, threadGroupsY, threadGroupsZ);




            }
            if (fusionDone) fusionDone = false;
        }


        public override void CleanUp()
        {
            Destroy(positionsOut1);
            Destroy(colorsOut1);
            Destroy(positionsOut2);
            Destroy(colorsOut2);
            Destroy(colorHistory);
            Destroy(positionHistory);
            Destroy(depthMap);
            foreach (var frame in frameBuffer)
                frame.Dispose();
            frameBuffer.Clear();
        }
    }
}